"""NVIDIA whitepaper research refresh; no renderer capability is promoted."""
REV = '20463fd355c817a50381343d9d12b7ac811d2e39'
BASE = 'https://github.com/NVIDIA-RTX/Whitepapers/blob/' + REV + '/'


def apply(sections, sources, source, section, table, cite):
    source('S113', 'NVIDIA clustered geometry and partitioned TLAS whitepaper', BASE + 'dx_clusters_and_ptlas/README.md',
           'Read complete English paper at pinned revision. Explains topology templates and sparse partition updates; announces DX12 preview and NVIDIA 621.01 support. Forest scale and game examples are vendor demonstrations, not Basix results.', date='2026-10-28', kind='vendor technical whitepaper',
           rights='CC BY 4.0 text; Microsoft/Remedy images have separate notices. Original Basix summary only; no paper images or code copied.')
    source('S114', 'NVIDIA real-time path tracing performance whitepaper', BASE + 'pt_performance_whitepaper/README.md',
           'Read complete English paper including case studies and references. End-to-end budgets, AS policy, hot/cold hit data, material LOD, sampling, caches, reconstruction, live state and mixed tracing. Vendor recommendations need scene-specific experiments.', kind='vendor technical whitepaper',
           rights='CC BY 4.0. Original Basix summary only; source timings and figures are not reproduced or relabeled as Basix measurements.')
    source('S115', 'Microsoft clustered geometry and PTLAS preview release', 'https://devblogs.microsoft.com/directx/clas-ptlas-preview/',
           'Full release article read 28 October. Agility 1.722.0-preview, DXC 1.10.2605.37-preview, Developer Mode, experimental enablement and capability query. CLAS dependency invalidation and ordered build barriers are explicit. Its comparison table has a pending correction for an unnecessary conventional build flag; do not use that table as a speedup forecast.', date='2026-10-28')
    source('S116', 'NVIDIA whitepaper license and image exceptions', BASE + 'dx_clusters_and_ptlas/LICENSE',
           'Folder-specific CC BY 4.0 with separately copyrighted Gears of War and CONTROL images. Root LICENSE delegates to folder terms; paper access does not grant an MIT code or SDK license.', kind='license', rights='Link only; no third-party media redistributed.')
    source('S117', 'Microsoft Agility SDK 1.620 retail and 1.722 preview overview', 'https://devblogs.microsoft.com/directx/agilitysdk-1-620-retail-and-1-722-preview/',
           'Complete release overview and feature-support appendix read. Separates retail SDK/API availability from per-feature driver support; SM6.10 remains preview with a December retail target. DXCGC graph runtime interfaces do not make SM6.10 Linear Algebra retail.', date='2026-10-28')
    # Update current source evaluation while retaining dated append-only roadmap notes.
    for s in sources:
        if s['id'] == 'S11':
            s['notes'] += ' Superseded preview availability: 28 October release S115 documents 1.722.0-preview; earlier table observation is historical.'
        elif s['id'] in ('S14', 'S15', 'S32', 'S33'):
            s['notes'] += ' Freshness correction: S115 now establishes an announced consumable preview and prerequisites. Earlier draft/index observations are historical; Basix has not installed or executed this DX12 path.'
    by = {s['id']: s for s in sections}
    by['dx-roadmap']['body'] = by['dx-roadmap']['body'].replace(
        'Conflicting official status: detail spec says preview; index says not-preview. Consumable SDK/driver combination unverified.',
        'Preview announced 28 October: Agility 1.722.0-preview and matching compiler/driver prerequisites; Basix DX12 execution remains unverified.')
    by['dx-roadmap']['body'] = by['dx-roadmap']['body'].replace(
        '<p><strong>Correction after rechecking:</strong> the rendered DXR2 specification explicitly says preview, despite the index’s older label. Basix therefore tracks the feature as “spec reports preview; package/driver implementation unverified,” rather than asserting a firm unavailable or shipping status.</p>',
        '<p><strong>28 October release correction:</strong> Microsoft now documents a DX12 clustered geometry/PTLAS preview. This supersedes the earlier index/spec conflict. Preview availability is distinct from tested Basix support; our Vulkan-first backend and existing driver are unchanged.</p>')
    by['dx-roadmap']['body'] += '<p>See the <a href="#nvidia-whitepapers">whitepaper evaluation</a> for prerequisites and adoption gates.</p>' + cite('S113', 'S115')
    by['dx-roadmap']['body'] += '<h3 id="agility-october-release">Agility 1.620 retail versus 1.722 preview</h3>' + table(['Release / topic', 'Implication for Basix'], [
        ('1.620 retail · diagnostics and submission', 'Dump files, batched commands and Fence Barriers Tier 1 enter retail. Tier 2 cross-queue waits remain preview; each feature still needs its own driver query.'),
        ('1.620 retail · shader delivery and ML', 'Partial Graphics Programs and DXCGC MLIR runtime interfaces are separate from SM6.10 Linear Algebra. API release does not establish driver coverage.'),
        ('1.722 preview · geometry and descriptors', 'CLAS/PTLAS/indirect AS builds are preview. GPU Timeline CopyDescriptors additionally requires Resource Binding Tier 4; not an automatic bindless-engine capability.'),
        ('SM6.10 · still preview', 'Microsoft targets early December with 1.621 retail. Treat that as a forecast and retain the current LinAlg preview gate.'),
        ('Feature matrix · independent support', 'The overview lists NVIDIA support for clustered AS but future driver support for Partial Graphics Programs, GPU descriptor copies and Driver Reported Messages. Never infer support for the entire SDK from one supported feature.')]) + '<p>These DirectX changes inform a possible future backend; they do not change Vulkan execution or replace Vulkan synchronization, pipeline-cache and descriptor contracts. No SDK, compiler or driver upgrade was performed.</p>' + cite('S117')
    by['research-map']['body'] += '<p><strong>Q10 · Whitepaper refresh:</strong> first resolve preview maturity; then select geometry and performance ideas that change Basix decisions. Stop when prerequisites, limitations and independent acceptance gates are explicit. No driver installation or renderer experiment is part of this research update.</p>'
    by['idea-pool']['body'] += '''<h3 id="nvidia-whitepapers">NVIDIA whitepapers: summary and implementation implications</h3>
<p>Reviewed 28 October 2026 at revision <code>20463fd355c817a50381343d9d12b7ac811d2e39</code>. Both complete English papers were read. <strong>Decision:</strong> retain Vulkan first, preserve the conventional BLAS/TLAS baseline, and prioritize final DLSS temporal quality before optional RT optimizations. These are evaluated proposals, not new engine execution results.</p>''' + cite('S113', 'S114') + table(['Idea / priority', 'Basix proposal', 'Acceptance and limits'], [
        ('Cluster templates · geometry research', 'Cook stable cluster topology and source-triangle/material IDs; instantiate positions separately for skinning or repeated terrain patterns. Map through a native Vulkan cluster adapter.', 'Compare identical rays/geometry with ordinary BLAS; test deformation, relocation, LOD and retirement. DX12 CLAS are not refittable; template instantiation is not conventional BLAS refit.'),
        ('Partitioned TLAS · large-world research', 'Persistent instance IDs, spatial partitions and a dynamic/global group; update changed partitions. Evaluate Vulkan partitioned AS independently.', 'Measure build plus traversal, scratch and persistent memory. Test migration, stale bounds, origin shifts and deletion. Partition overlap and frequent repartitioning can erase gains.'),
        ('AS maintenance scheduler · deferred', 'Budget both instance count and processed geometry; combine proximity, contribution and maximum age to avoid starving unseen but important objects.', 'Compare refit/rebuild/compaction at matched geometry and motion. Include thin shadow casters, mirrors, offscreen contributors and sudden movement; counters alone must not decide correctness.'),
        ('Hit-data and material LOD · deferred', 'Split compact hot attributes from cold authoring data; select a few material classes by ray purpose. Profile inline RayQuery against ray pipelines only when material complexity warrants it.', 'Check normals, UV footprints, glossy detail and cache bias against the reference. Keep current numeric ray-boundary position data: shading bandwidth advice does not justify weakening robust spawn geometry.'),
        ('Per-signal budgets · future measurement', 'Separate direct visibility, diffuse/specular transport and cache work; time AS, tracing, reconstruction and total frame, with scratch/VRAM peaks.', 'Equal-time final-image and temporal error across presets. GPU timers remain distinct from CPU elapsed time and the private chat cost meter; no Basix speedup is established.'),
        ('Temporal reconstruction · next DLSS gate', 'Build reference/ROI sequences for disocclusion, thin moving geometry, glossy motion and lighting changes; retain accepted guide and SDK lifecycle checks.', 'Define sequence metrics and thresholds before running. Super Resolution does not establish PT denoising; RR/NRD contracts and any future reservoir decorrelation require separate work.'),
        ('SER, OMM and radiance caches · optional', 'Test one bottleneck at a time, with capability-selected shaders and native resource ownership. Keep unbiased reference transport and conventional fallbacks.', 'Measure live state, occupancy, any-hit cost and whole-frame quality. Force-opaque cache updates and deterministic truncation introduce bias; do not silently change the reference estimator.')]) + '''
<figure class="pipeline"><div>Stable source triangles → clusters + topology templates</div><div>Current positions → CLAS → cluster BLAS</div><div>Persistent instances → conventional TLAS / optional partitioned AS</div><div>Lighting signals → reconstruction → final temporal quality</div><figcaption>Proposed dependency flow. Each AS build stage needs its own resource lifetime and visibility barriers; API names and limits remain backend-specific.</figcaption></figure>
<h4>Preview availability and API boundaries</h4><p>Microsoft specifies Agility 1.722.0-preview, DXC 1.10.2605.37-preview, Developer Mode and experimental feature enablement plus a runtime support query. NVIDIA names driver 621.01; our recorded local 617.42 results do not test it. No driver or SDK was installed for this research. CLAS references have no per-cluster transform in a cluster BLAS, and changing referenced content/address invalidates dependent structures. Separate dependent build stages with barriers; operations within one indirect batch must be independent.</p>''' + cite('S113', 'S115') + '''
<p>For Vulkan, use the existing <a href="#vulkan-features">extension adoption map</a>: <code>VK_NV_cluster_acceleration_structure</code> and <code>VK_NV_partitioned_acceleration_structure</code> are independent native contracts. LinAlg/cooperative matrices address matrix computation, whereas CLAS/PTLAS address acceleration structures; neither implies the other. NoGraphicsAPI does not acquire these RT APIs automatically; the Basix native Vulkan adapter must own their integration.</p>
<h4>Summary and lessons learned</h4><p>Reuse topology and unchanged scene regions at different levels; neither replaces the other. Optimize total reconstructed frame quality, not isolated rays per second. Keep scalable biased approximations explicit and compare them with the original reference. Vendor case studies are useful hypotheses, not transferable speedups: Microsoft also flags a pending correction to its conventional-build comparison. Public paper licenses do not license an SDK or game artwork for the MIT core.</p>''' + cite('S114', 'S115', 'S116')
    by['summary']['body'] += '<p><a href="#nvidia-whitepapers">New NVIDIA whitepapers evaluated</a>: DX12 preview maturity corrected; cluster templates, partitioned updates and performance gates added without promoting implementation status.</p>'
    by['lessons']['body'] += '<p><strong>Research freshness matters:</strong> the 28 October DX12 preview announcement supersedes the earlier draft-only evidence. Release availability, runtime capability, executed integration and measured benefit remain four separate claims.</p>' + cite('S115')


def enrich_library(library):
    for f in library['findings']:
        if f['id'] == 'F4':
            f['claim'] = 'DXR1.2 is retail; LinAlg and the 28 October clustered geometry/PTLAS release are preview paths. Basix remains Vulkan first; the announced DX12 path has not been executed locally. UE6 remains a future target.'
            f['evidence'].append(dict(source_id='S115', locator='Availability and prerequisites', relation='updates', note='New preview release supersedes earlier index/spec availability conflict.'))
    library['questions'].append(dict(id='Q10', title='Which NVIDIA whitepaper ideas change Basix priorities?', priority='high', rationale='Resolve new preview availability, then preserve Vulkan contracts, MIT boundaries and independent performance/quality gates.', status='answered within research scope', depends_on=['Q2', 'Q8']))
    for id, title, claim, ids in [
        ('F27', 'CLAS templates and PTLAS target separate update costs', 'Reusable topology reduces local geometry-build work; sparse partition updates reduce scene-wide instance work. Their lifetime and synchronization dependencies still require explicit backend integration.', ['S113', 'S115']),
        ('F28', 'Performance recommendations require final-image acceptance', 'Per-signal budgets, compact hit data and selective AS updates are candidates for measured experiments. Current DLSS integration acceptance does not establish temporal image quality or PT denoising.', ['S114'])]:
        library['findings'].append(dict(id=id, title=title, question_ids=['Q10'], topic='rendering', claim=claim, evidence_type='primary-source research and Basix design inference', confidence='high for documented contracts; unmeasured for Basix benefit', context='Vulkan-first NoGraphicsAPI foundation with native RT/SDK adapters.', strengths='Complete source read, preview announcement corroboration and explicit adoption gates.', limitations='No advanced AS execution, new GPU profile or image-quality experiment in this update.', implications='Keep optional optimizations deferred; proceed with the pending DLSS temporal/detail-quality definition.', tags=['whitepapers', 'CLAS', 'PTLAS', 'path tracing', 'Vulkan', 'DLSS'], evidence=[dict(source_id=s, locator='Named sections in complete English paper / preview release', relation='supports', note='Source guidance and local implementation are distinct.') for s in ids]))
    library['search_log'].append(dict(date='2026-10-28', phase='targeted update', engine='Pinned NVIDIA repository and Microsoft release articles', query='NVIDIA Whitepapers cluster templates PTLAS performance reconstruction Agility 1.620 1.722 SM6.10', source_ids=['S113', 'S114', 'S115', 'S116', 'S117'], outcome='Read both English papers, licenses and Microsoft overview/support matrix; corrected preview maturity while preserving SM6.10 preview status; added proposed gates without implementation promotion.'))
    library['scope_changes'].append('Evaluated the user-supplied NVIDIA whitepaper repository; no non-DLSS M3 implementation or driver installation authorized by this research addition.')
